def Cdf.diffs : {v n : ℕ} → (Fin n → Fin 5 → Fin v) → Multiset (Fin v) :=
fun {v n} B => Multiset.map (fun t => B t.1 t.2.1 - B t.1 t.2.2) {t | t.2.1 ≠ t.2.2}.val
def Cdf.IsCDF : {v n : ℕ} → (Fin n → Fin 5 → Fin v) → Prop :=
fun {v n} B =>
  (∀ (i : Fin n), Function.Injective (B i)) ∧
    (∀ (d : Fin v), ↑d ≠ 0 → Multiset.count d (Cdf.diffs B) = 1) ∧
      ∀ (d : Fin v), ↑d = 0 → Multiset.count d (Cdf.diffs B) = 0
def Cdf.Target : ℕ → Prop :=
fun v => ∃ n B, Cdf.IsCDF B
